using System;using System.IO;using System.Text;using Frociart;
internal static class JavaScriptHostExamples {
 static int Main(string[] args){try{string root=args[0];foreach(var example in new[]{new[]{"FileExample","DICHIARA riga: TESTO\nAPRI_FILE LETTURA \"input.txt\"\nAPRI_FILE SCRITTURA \"output.txt\"\nMENTRE non EOF() FAI\nLEGGI_FILE riga\nSCRIVI_FILE riga\nFINE MENTRE\nCHIUDI_FILE LETTURA\nCHIUDI_FILE SCRITTURA\nSTAMPA \"copiato\""},new[]{"TurtleExample",FlowTurtle.Example},new[]{"UnicodeExample","STAMPA π\nSTAMPA \"È 🐢\""},new[]{"InputExample","DICHIARA n: REALE\nLEGGI n\nSTAMPA n+1"},new[]{"ChunkInputExample","LEGGI x\nLEGGI y\nSTAMPA len(x)\nSTAMPA y"},new[]{"DepthExample","FUNZIONE ricorri(n: INTERO) -> INTERO risultato\nrisultato=ricorri(n+1)\nFINE FUNZIONE\nSTAMPA ricorri(0)"}}){var program=FlowSource.Compile(FlowPseudocode.Decode(example[1]));foreach(bool typed in new[]{false,true}){var text=FlowJavaScript.Generate(program,typed);File.WriteAllText(Path.Combine(root,example[0]+(typed?".cts":".cjs")),text.Text,new UTF8Encoding(false));}}Console.WriteLine("JAVASCRIPT_HOST_EXAMPLES PASS");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
